const NAME_SEPARATORS = ["・", "＝", ""];
window.USED_ENEMY_BASE_KEYS = window.USED_ENEMY_BASE_KEYS || new Set();

function pseudoHash(floor, salt = 1) { return Math.sin(floor * 9999 + salt * 12345) * 10000 - Math.floor(Math.sin(floor * 9999 + salt * 12345) * 10000); }

// 💡 異なる音節のみを1〜3音節で組み合わせる関数
function generateUniqueN1Word(n1List, floor) {
    const count = Math.floor(pseudoHash(floor, 1.7) * Math.min(3, n1List.length)) + 1; // 1〜3音節（リスト要素数を上限）
    const available = [...n1List];
    let result = "";

    for (let i = 0; i < count; i++) {
        const idx = Math.floor(pseudoHash(floor, 2.1 + i) * available.length);
        result += available[idx];
        available.splice(idx, 1); // 選んだ音節を除外して被りを防止
    }
    return result;
}
window.generateEnemyName = function(raceId, targetFloor) {
    const table = window.ENEMY_NAME_TABLE[raceId], fallbackBaseName = (raceId === 'goblin') ? "ゴブリン" : (raceId === 'zombi') ? "ゾンビ" : (raceId === 'eyes') ? "アイズ" : "魔物";
    if (!table) return `${targetFloor}階の${fallbackBaseName}`;

    // 1. 全有効パターンの決定論的一括算出（1〜3音節N1＋N2 × N3 の一意ペア）
    const n1List = [...table.n1], prefixCandidates = [...table.n2];
    for (let i = 0; i < n1List.length; i++) {
        prefixCandidates.push(n1List[i]);
        for (let j = 0; j < n1List.length; j++) {
            if (i !== j) {
                prefixCandidates.push(n1List[i] + n1List[j]);
                for (let k = 0; k < n1List.length; k++) if (k !== i && k !== j) prefixCandidates.push(n1List[i] + n1List[j] + n1List[k]);
            }
        }
    }
    const uniquePairs = [];
    for (const prefix of prefixCandidates) for (const n3 of table.n3) uniquePairs.push({ prefix, n3 });

    // 2. 1vs1 完全決定論的一元インデックス算出（余計な脱落判定を全撤去して何千階でも正常生成）
    const totalCandidates = uniquePairs.length;
    let raceSalt = 0; for (let i = 0; i < raceId.length; i++) raceSalt += raceId.charCodeAt(i) * (i + 1);
    const uniqueIndex = (targetFloor * 10007 + raceSalt * 97) % totalCandidates;

    // 3. パーツペア単位で「語順」と「区切り記号」を一元固定（被り・誤脱落の完全遮断）
    const chosen = uniquePairs[uniqueIndex];
    const pairKey = [chosen.prefix, chosen.n3].sort().join('');
    let keyHash = 0; for (let i = 0; i < pairKey.length; i++) keyHash += pairKey.charCodeAt(i) * (i + 1);

    const isN3First = (keyHash % 2 === 0), firstWord = isN3First ? chosen.n3 : chosen.prefix, lastWord = isN3First ? chosen.prefix : chosen.n3;
    const sep = NAME_SEPARATORS[keyHash % NAME_SEPARATORS.length];
    return `${firstWord}${sep}${lastWord}`;
};

