window.generateFlavorText = function(race, targetFloor) {
    const P = ["メラメラとあふれ出る狂気を放つ。", "異様な気配で徘徊している。", "狂暴化が著しく進んでいる。", "深層の瘴気に浸食されている。", "鋭い殺気がこちらに向いている。", "全身から禍々しいオーラを溢れさせている。", "古代の呪導線が浮き出ている。", "過剰な闘争本能で身体を震わせている。", "歪んだ闇空間から現れ出ている。", "周囲の魔素を吸収して脈動している。", "狂乱の領域に達している。", "獲物の血を求めて暗闇を彷徨っている。", "空間に不気味な紋様が浮かんでいる。", "大気を乱しながら殺気を漲らせている。", "従来の個体とは明らかに異なる動作を見せている。", "「ギリギリ」という不気味な摩擦音。"];
    const M = [`${race.name}の変異体だ。`, `深層における暴走${race.name}種だ。`, "きわめて凶悪な魔物だ。", "塔の深部で進化した特殊個体だ。", "原種を遥かに凌駕する異形体だ。", `古代魔力の爆発により生まれた変種${race.name}だ。`, "羊皮紙にも記載の少ない未知の危険種だ。", "邪気に染まった強大な脅威だ。", "極めて高い生命力を宿す化け物だ。", "空間の歪みが引き起こした変異個体だ。", "深層を縄張りとする危険なモンスターだ。", `従来の常識が通用しない異常${race.name}種だ。`, "極めて攻撃的な属性変異種だ。", "防衛本能が極限まで跳ね上がった個体だ。", `侵入者を容赦なく排斥する${race.name}種だ。`, `${race.name}対応の亜種。`];
    const S = ["厳重に警戒せよ。", "先制攻撃で一気に仕留めろ。", "距離を取って慎重に戦え。", "弱点属性を見極めて撃破せよ。", "油断すれば一瞬で肉体を噛み砕かれるぞ。", "長引かせず短期決戦で挑め。", "敵の不審な大技の兆候に注意せよ。", "背後を取られないよう間合いを保て。", "万全の体制を整えてから挑むべし。", "決して態勢を崩さず冷静に対処せよ。", "即座に魔法攻撃を叩き込め。", "相手の猛攻に備えて防衛を固めよ。", "退路を意識しつつ確実に仕留めろ。", "一撃の重さを警戒し、回避に専念せよ。", "持てる全力を惜しみなく注ぎ込め。", "耐性を調べて注意しろ。"];

    const seededRandom = seed => Math.sin(seed) * 10000 - Math.floor(Math.sin(seed) * 10000);
    const p = P[Math.floor(seededRandom(targetFloor * 7) * P.length)];
    const m = M[Math.floor(seededRandom(targetFloor * 8) * M.length)];
    const s = S[Math.floor(seededRandom(targetFloor * 9) * S.length)];
    
    return [p, m, s].sort(() => 0.5 - seededRandom(targetFloor)).join(" ");
};
// ==========================================
// ⚔️ 【1か所完結】敵の攻撃モーション自動割り込みシステム（攻撃時のみ4枚目発動版）
// ==========================================
(function() {
    // 1. 攻撃フレーム（4, 8, 12, 16）を一瞬だけ再生する関数
// 1. 待機パターンに連動した攻撃フレーム（4, 8, 12, 16）を再生する関数
    window.playEnemyAttackMotion = function(durationMs = 400) {
        const atkFrame = window.currentEnemyAttackFrame || 4;

        window.enemyAttackFrameNum = atkFrame;
        const graphicEl = document.getElementById("e-sprite-graphic");
        const floor = (typeof window.curIdx === 'number' && window.curIdx >= 0) ? (window.curIdx + 1) : 1;
        const stageData = (typeof getStageData === 'function') ? getStageData(floor) : (window.STAGES && window.STAGES[window.curIdx]);
        // 👇 【ピンポイント③】1044行目のすぐ下に貼り付け
        if (stageData && stageData.atkFrame && graphicEl && graphicEl.src) {
            window.enemyAttackFrameNum = stageData.atkFrame;
            graphicEl.src = graphicEl.src.replace(/_[^_.]+\.png$/i, `_${stageData.atkFrame}.png`);
            clearTimeout(window._enemyAtkMotionTimer);
            window._enemyAtkMotionTimer = setTimeout(() => { window.enemyAttackFrameNum = null; }, durationMs);
            return;
        }
        const dynamicArr = (stageData && window.MASTER_ANIM_MAP && window.MASTER_ANIM_MAP[stageData.type]) ? window.MASTER_ANIM_MAP[stageData.type] : null;
        
        if (graphicEl && dynamicArr) {
            const path = dynamicArr[atkFrame - 1] || dynamicArr[3] || dynamicArr[0];

      
            graphicEl.src = window.getCleanAssetPath(path);
        }

        clearTimeout(window._enemyAtkMotionTimer);
        window._enemyAtkMotionTimer = setTimeout(() => {
            window.enemyAttackFrameNum = null;
        }, durationMs);
    };

    // 2. 大技・個別アクション（executeEnemySpecial）のフック処理（攻撃時のみ4枚目発動版）
    const origExecuteSpecial = window.executeEnemySpecial;
    if (typeof origExecuteSpecial === 'function') {
        window.executeEnemySpecial = function(...args) {
            const res = origExecuteSpecial.apply(this, args);
            // 防御やバフ（dmg === 0）以外の、実際の攻撃・呪文アクションの時だけ4枚目を再生
            if (res && res.dmg > 0) {
                window.playEnemyAttackMotion(400);
            }
            return res;
        };
    }

    // 3. 通常攻撃の突進（#e-sprite-container の transform 変化）を自動検知して4枚目を再生
    window.addEventListener('DOMContentLoaded', () => {
        const eContainer = document.getElementById('e-sprite-container');
        if (eContainer) {
            const observer = new MutationObserver(() => {
                const tf = eContainer.style.transform || "";
                if (tf.includes("translateX(-") && !window.enemyAttackFrameNum) {
                    window.playEnemyAttackMotion(400);
                }
            });
            observer.observe(eContainer, { attributes: true, attributeFilter: ['style'] });
        }
    });
})();
// =============================================================================
// 🧪 【デバッグ専用】1192コンソール＆F12コンソールから技を即座にテスト発火！
// =============================================================================
window.testSkill = function(skillKeyOrNo) {
    if (skillKeyOrNo === undefined || skillKeyOrNo === "") {
        if (window.MONSTER_ACTION_MASTER) {
            const list = Object.entries(window.MONSTER_ACTION_MASTER)
                .filter(([k]) => !isNaN(k))
                .map(([k, v]) => `${k}: ${v.name} (${v.id})`);
            console.log("📜 【登録済みの敵スキル一覧】\n" + list.join("\n"));
        }
        return;
    }

    const floor = (typeof window.curIdx === 'number' && window.curIdx >= 0) ? (window.curIdx + 1) : 1;
    const rawData = (typeof getStageData === 'function' ? getStageData(floor) : null)
                 || (window.STAGES && window.STAGES[window.curIdx])
                 || { name: "テスト魔物", atk: 20, int: 20, type: "goblin" };

    const testData = { ...rawData, isAutoGenerated: true, actions: [skillKeyOrNo] };
    const effScr = document.getElementById('eff-scr');
    const battleLog = document.getElementById('battle-log');
    const baseDmg = Number(testData.atk) || 20;

    if (effScr) effScr.className = "";
    const res = window.executeEnemySpecial(testData, baseDmg, "", effScr, true);

    const finalDmg = Math.max(0, Math.round(res.dmg || 0));
    if (finalDmg > 0) {
        window.pHp = Math.max(0, (window.pHp || 100) - finalDmg);
        if (typeof createDmgPop === 'function') createDmgPop(finalDmg, true);
        if (typeof updateHpUI === 'function') updateHpUI();
    }
    if (battleLog) battleLog.innerHTML = `🧪[TEST] ${res.logTxt}`;
    if (typeof window.updateStatusBadgesUI === 'function') window.updateStatusBadgesUI();

    setTimeout(() => { if (effScr) effScr.className = ""; }, 1200);
    console.log(`✅ テスト発火: [${skillKeyOrNo}] ➔ ダメージ: ${finalDmg}`);
};